// 吉伊記帳小屋 v2 - Cloudflare Worker API + 靜態網站
// 需要在 Worker 綁定名稱為 DB 的 D1 資料庫，並執行 migrations/0001_initial.sql。
const INIT_SQL = ["CREATE TABLE IF NOT EXISTS users (\n  id TEXT PRIMARY KEY,\n  username TEXT NOT NULL UNIQUE COLLATE NOCASE,\n  display_name TEXT NOT NULL,\n  salt TEXT NOT NULL,\n  password_hash TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)", "CREATE TABLE IF NOT EXISTS ledgers (\n  id TEXT PRIMARY KEY,\n  name TEXT NOT NULL,\n  invite_code TEXT NOT NULL UNIQUE,\n  owner_id TEXT NOT NULL REFERENCES users(id),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)", "CREATE TABLE IF NOT EXISTS memberships (\n  user_id TEXT PRIMARY KEY REFERENCES users(id),\n  ledger_id TEXT NOT NULL REFERENCES ledgers(id),\n  role TEXT NOT NULL CHECK(role IN ('owner','member')),\n  joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)", "CREATE INDEX IF NOT EXISTS memberships_ledger_idx ON memberships(ledger_id)", "CREATE TABLE IF NOT EXISTS sessions (\n  token_hash TEXT PRIMARY KEY,\n  user_id TEXT NOT NULL REFERENCES users(id),\n  expires_at INTEGER NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)", "CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id)", "CREATE TABLE IF NOT EXISTS login_attempts (\n  username TEXT PRIMARY KEY,\n  failed_count INTEGER NOT NULL DEFAULT 0,\n  window_start INTEGER NOT NULL DEFAULT 0\n)", "CREATE TABLE IF NOT EXISTS items (\n  ledger_id TEXT NOT NULL REFERENCES ledgers(id),\n  collection TEXT NOT NULL,\n  item_id TEXT NOT NULL,\n  payload TEXT NOT NULL,\n  updated_by TEXT NOT NULL REFERENCES users(id),\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY(ledger_id, collection, item_id)\n)", "CREATE TABLE IF NOT EXISTS changes (\n  seq INTEGER PRIMARY KEY AUTOINCREMENT,\n  ledger_id TEXT NOT NULL REFERENCES ledgers(id),\n  collection TEXT NOT NULL,\n  item_id TEXT NOT NULL,\n  payload TEXT,\n  deleted INTEGER NOT NULL DEFAULT 0,\n  changed_by TEXT NOT NULL REFERENCES users(id),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)", "CREATE INDEX IF NOT EXISTS changes_ledger_seq_idx ON changes(ledger_id, seq)"];

// 首次綁定全新 D1 時，自動建立資料表。SQL 檔案也保留供手動執行或復原。
let schemaPromise=null;
async function ensureSchema(db){
 if(!schemaPromise){
  schemaPromise=(async()=>{
   const existing=await db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='users'").first();
   if(!existing)await db.batch(INIT_SQL.map(q=>db.prepare(q)));
  })().catch(e=>{schemaPromise=null;throw e});
 }
 return schemaPromise;
}

const allowedCollections = new Set(['accounts','categories','projects','transactions','recurring','templates','invoices','profiles','settings']);
const maxSessionAge = 60 * 60 * 24 * 30;
const enc = new TextEncoder();
const json = (data, status = 200, headers = {}) => new Response(JSON.stringify(data), {status, headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff',...headers}});
const err = (message, status=400) => json({ok:false,error:message},status);
const random = (length=24) => {let bytes=crypto.getRandomValues(new Uint8Array(length));return [...bytes].map(v=>v.toString(16).padStart(2,'0')).join('')};
const hashHex = async (input) => [...new Uint8Array(await crypto.subtle.digest('SHA-256',enc.encode(input)))].map(v=>v.toString(16).padStart(2,'0')).join('');
const encodeHex = x => [...new Uint8Array(x)].map(v=>v.toString(16).padStart(2,'0')).join('');
const derivePassword = async (password,salt) => {
  const key = await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveBits']);
  const bits = await crypto.subtle.deriveBits({name:'PBKDF2',salt:enc.encode(salt),iterations:100000,hash:'SHA-256'},key,256);
  return encodeHex(bits);
};
const cookie = (token, clear=false) => `chii_session=${clear?'':token}; Path=/; HttpOnly; Secure; SameSite=Lax; ${clear?'Max-Age=0':`Max-Age=${maxSessionAge}`}`;
const limited = (s,max) => typeof s === 'string' ? s.trim().slice(0,max) : '';
const usernameOK = s => /^[a-zA-Z0-9._-]{3,32}$/.test(s||'');
const pwdOK = s => typeof s === 'string' && s.length >= 10 && s.length <= 128;
const secureCompare = (a,b) => {if(a.length!==b.length)return false;let x=0;for(let i=0;i<a.length;i++)x|=a.charCodeAt(i)^b.charCodeAt(i);return x===0};
const userPublic = u => ({id:u.id,username:u.username,displayName:u.display_name});
async function bodyJSON(req){if(!req.headers.get('content-type')?.includes('application/json'))throw new Error('請使用 JSON 格式');const t=await req.text();if(t.length>1200000)throw new Error('資料超過單次上傳限制');return JSON.parse(t)}
async function authenticate(req,db){
 const match=(req.headers.get('cookie')||'').match(/(?:^|;\s*)chii_session=([0-9a-f]{48})/);
 if(!match)return null;
 const tokenHash=await hashHex(match[1]);const now=Math.floor(Date.now()/1000);
 return db.prepare(`SELECT u.id,u.username,u.display_name,m.ledger_id,m.role,s.token_hash,l.name AS ledger_name,l.invite_code,l.owner_id FROM sessions s JOIN users u ON u.id=s.user_id JOIN memberships m ON m.user_id=u.id JOIN ledgers l ON l.id=m.ledger_id WHERE s.token_hash=? AND s.expires_at>?`).bind(tokenHash,now).first();
}
async function members(db,id){const r=await db.prepare('SELECT u.id, u.username, u.display_name, m.role FROM memberships m JOIN users u ON m.user_id=u.id WHERE m.ledger_id=? ORDER BY CASE m.role WHEN \'owner\' THEN 0 ELSE 1 END,m.joined_at').bind(id).all();return r.results.map(u=>({...userPublic(u),role:u.role}));}
async function createSession(db,userId){const token=random(24),digest=await hashHex(token);await db.prepare('INSERT INTO sessions(token_hash,user_id,expires_at) VALUES (?,?,?)').bind(digest,userId,Math.floor(Date.now()/1000)+maxSessionAge).run();return token;}
async function register(req,db){
 const data=await bodyJSON(req),username=limited(data.username,32).toLowerCase(),displayName=limited(data.displayName,24),password=data.password,inviteCode=limited(data.inviteCode,80).toUpperCase().replace(/\s/g,'');
 if(!usernameOK(username))return err('帳號須為 3～32 位英文、數字、句點、底線或連字號');
 if(!displayName||displayName.length>24)return err('請填寫 1～24 個字的暱稱');
 if(!pwdOK(password))return err('密碼至少 10 個字元，最多 128 個');
 if(await db.prepare('SELECT id FROM users WHERE username=?').bind(username).first())return err('此帳號已有人使用',409);
 let ledger=null;if(inviteCode){ledger=await db.prepare('SELECT id FROM ledgers WHERE invite_code=?').bind(inviteCode).first();if(!ledger)return err('邀請碼不存在，請向另一半確認',404);const count=await db.prepare('SELECT COUNT(*) AS n FROM memberships WHERE ledger_id=?').bind(ledger.id).first();if(count.n>=2)return err('此共用帳本已達兩人上限',409)}
 const userId=random(16),salt=random(16),passwordHash=await derivePassword(password,salt),ledgerId=ledger?.id||random(16);
 try{
  const queries=[db.prepare('INSERT INTO users(id,username,display_name,salt,password_hash) VALUES(?,?,?,?,?)').bind(userId,username,displayName,salt,passwordHash)];
  if(!ledger)queries.push(db.prepare('INSERT INTO ledgers(id,name,invite_code,owner_id) VALUES(?,?,?,?)').bind(ledgerId,'我們的記帳小屋',random(8).toUpperCase(),userId));
  queries.push(db.prepare(`INSERT INTO memberships(user_id,ledger_id,role) SELECT ?,? ,? WHERE (SELECT COUNT(*) FROM memberships WHERE ledger_id=?) < 2`).bind(userId,ledgerId,ledger?'member':'owner',ledgerId));
  await db.batch(queries);
  const membership=await db.prepare('SELECT user_id FROM memberships WHERE user_id=?').bind(userId).first();
  if(!membership){await db.prepare('DELETE FROM users WHERE id=?').bind(userId).run();return err('共用帳本已滿兩位成員',409)}
  return json({ok:true,member:userPublic({id:userId,username,display_name:displayName})},201,{'set-cookie':cookie(await createSession(db,userId))});
 }catch(e){console.error('REGISTER_UNEXPECTED_FAILED',e);if(String(e).includes('UNIQUE'))return err('帳號或邀請碼已存在，請更換帳號重試',409);throw e}
}
async function login(req,db){
 const data=await bodyJSON(req),username=limited(data.username,32).toLowerCase(),password=data.password||'';if(!usernameOK(username)||typeof password!=='string')return err('帳號或密碼錯誤',401);
 const now=Math.floor(Date.now()/1000),attempt=await db.prepare('SELECT failed_count,window_start FROM login_attempts WHERE username=?').bind(username).first();
 if(attempt?.failed_count>=8&&now-attempt.window_start<900)return err('登入嘗試過多，請 15 分鐘後再試',429);
 const u=await db.prepare('SELECT id,username,display_name,salt,password_hash FROM users WHERE username=?').bind(username).first();
 const calculated=await derivePassword(password,u?.salt||'invalid-salt-for-unknown-user');
 if(!u||!secureCompare(calculated,u.password_hash)){
  const count=attempt&&now-attempt.window_start<900?attempt.failed_count+1:1,from=attempt&&now-attempt.window_start<900?attempt.window_start:now;
  await db.prepare('INSERT INTO login_attempts(username,failed_count,window_start) VALUES(?,?,?) ON CONFLICT(username) DO UPDATE SET failed_count=excluded.failed_count,window_start=excluded.window_start').bind(username,count,from).run();
  return err('帳號或密碼錯誤',401);
 }
 await db.prepare('DELETE FROM login_attempts WHERE username=?').bind(username).run();
 return json({ok:true,member:userPublic(u)},200,{'set-cookie':cookie(await createSession(db,u.id))});
}
async function getSync(url,db,user){
 const since=Math.max(0,Math.floor(Number(url.searchParams.get('since'))||0));
 const latest=await db.prepare('SELECT COALESCE(MAX(seq),0) AS n FROM changes WHERE ledger_id=?').bind(user.ledger_id).first();
 if(since===0){const data=await db.prepare('SELECT collection,item_id,payload FROM items WHERE ledger_id=?').bind(user.ledger_id).all();return json({ok:true,full:true,cursor:latest.n,items:data.results.map(r=>({collection:r.collection,id:r.item_id,value:JSON.parse(r.payload)})),members:await members(db,user.ledger_id)})}
 const r=await db.prepare('SELECT seq,collection,item_id,payload,deleted FROM changes WHERE ledger_id=? AND seq>? ORDER BY seq ASC LIMIT 250').bind(user.ledger_id,since).all();
 const last=r.results.length?r.results[r.results.length-1].seq:latest.n;
 return json({ok:true,full:false,cursor:last,hasMore:r.results.length>=250,items:r.results.map(v=>({collection:v.collection,id:v.item_id,value:v.deleted?null:JSON.parse(v.payload),deleted:!!v.deleted})),members:await members(db,user.ledger_id)});
}
async function patchSync(req,db,user){
 const data=await bodyJSON(req);if(!Array.isArray(data.ops)||data.ops.length<1||data.ops.length>40)return err('每次最多同步 40 筆資料');
 const stmts=[];
 for(const op of data.ops){
  if(!op||!allowedCollections.has(op.collection)||typeof op.id!=='string'||op.id.length>120||!op.id||op.collection==='settings'&&op.id!=='main')return err('有不支援的同步項目');
  if(op.deleted){
   if(op.collection==='profiles' && op.id!==user.id)return err('只能刪除自己的頭像',403);
   stmts.push(db.prepare('DELETE FROM items WHERE ledger_id=? AND collection=? AND item_id=?').bind(user.ledger_id,op.collection,op.id));
   stmts.push(db.prepare('INSERT INTO changes(ledger_id,collection,item_id,payload,deleted,changed_by) VALUES(?,?,?,?,1,?)').bind(user.ledger_id,op.collection,op.id,null,user.id));
  }else{
   if(!op.value||typeof op.value!=='object'||Array.isArray(op.value))return err('同步內容格式錯誤');
   if(op.collection==='profiles' && (op.id!==user.id || op.value.id!==user.id || (op.value.avatar && (!/^data:image\/jpeg;base64,/.test(op.value.avatar) || op.value.avatar.length>50000))))return err('頭像只能由本人更新，圖片上限為 50KB',403);
    if(op.collection==='transactions'&&!['expense','income','transfer'].includes(op.value.kind))return err('不支援應收或應付交易');
   if(op.collection==='accounts'&&!['cash','bank','digital','credit','epay','investment'].includes(op.value.type))return err('帳戶類型不正確');
   const payload=JSON.stringify(op.value);if(payload.length>380000)return err('單筆記錄或收據圖片過大，請縮小附件');
   stmts.push(db.prepare('INSERT INTO items(ledger_id,collection,item_id,payload,updated_by) VALUES(?,?,?,?,?) ON CONFLICT(ledger_id,collection,item_id) DO UPDATE SET payload=excluded.payload,updated_by=excluded.updated_by,updated_at=CURRENT_TIMESTAMP').bind(user.ledger_id,op.collection,op.id,payload,user.id));
   stmts.push(db.prepare('INSERT INTO changes(ledger_id,collection,item_id,payload,deleted,changed_by) VALUES(?,?,?,?,0,?)').bind(user.ledger_id,op.collection,op.id,payload,user.id));
  }
 }
 await db.batch(stmts);return json({ok:true,saved:data.ops.length});
}
const chiiBackend = {
 async fetch(req,env){
  const url=new URL(req.url),path=url.pathname;
  if(!path.startsWith('/api/'))return env.ASSETS?env.ASSETS.fetch(req):err('未設定靜態檔案 ASSETS 綁定',503);
  if(req.method==='OPTIONS')return err('不允許跨站請求',403);
  if(!env.DB)return err('尚未綁定 D1 資料庫（請設定 DB binding）',503);
  if(!['GET','POST'].includes(req.method))return err('不支援的操作',405);
  try{await ensureSchema(env.DB)}catch(e){console.error('D1 schema error',e);return err('D1 資料庫初始化失敗，請檢查 DB 綁定與權限',503)}
  if(req.method==='POST'){
   const origin=req.headers.get('origin');if(origin!==url.origin)return err('安全性驗證失敗（需要同一網址登入）',403);
  }
  try{
   if(path==='/api/health'&&req.method==='GET'){await env.DB.prepare('SELECT id FROM users LIMIT 1').first();return json({ok:true,service:'chii-ledger-v2'})}
   if(path==='/api/auth/register'&&req.method==='POST')return await register(req,env.DB);
   if(path==='/api/auth/login'&&req.method==='POST')return await login(req,env.DB);
   const user=await authenticate(req,env.DB);if(!user)return err('尚未登入或登入已過期',401);
   if(path==='/api/auth/me'&&req.method==='GET')return json({ok:true,user:userPublic(user),ledger:{id:user.ledger_id,name:user.ledger_name,inviteCode:user.role==='owner'?user.invite_code:null,role:user.role},members:await members(env.DB,user.ledger_id)});
   if(path==='/api/auth/logout'&&req.method==='POST'){
    const token=req.headers.get('cookie')?.match(/(?:^|;\s*)chii_session=([0-9a-f]{48})/)?.[1];if(token)await env.DB.prepare('DELETE FROM sessions WHERE token_hash=?').bind(await hashHex(token)).run();return json({ok:true},200,{'set-cookie':cookie('',true)});
   }
   if(path==='/api/auth/rotate-invite'&&req.method==='POST'){
    if(user.role!=='owner')return err('只有帳本建立者能更新邀請碼',403);
    const newCode=random(8).toUpperCase();await env.DB.prepare('UPDATE ledgers SET invite_code=? WHERE id=?').bind(newCode,user.ledger_id).run();return json({ok:true,inviteCode:newCode});
   }
   if(path==='/api/sync'&&req.method==='GET')return await getSync(url,env.DB,user);
   if(path==='/api/sync'&&req.method==='POST')return await patchSync(req,env.DB,user);
   return err('找不到 API',404);
  }catch(e){console.error('API_UNEXPECTED_ERROR',path,e);if(e instanceof SyntaxError)return err('JSON 格式錯誤');if(e.message==='資料超過單次上傳限制'||e.message==='請使用 JSON 格式')return err(e.message);if(String(e).includes('no such table'))return err('資料庫尚未執行建表 SQL',503);return err('伺服器發生錯誤，請稍後再試',500)}
 }
};


